def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # A solid 3x3 square is a source: extend its middle row and column.
    sources = []
    # Find monochrome filled squares of at least 3x3, of different colors/sizes.
    for color in set(v for row in grid for v in row if v):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if len(cells) < 9:
            continue
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if r1-r0 == c1-c0 and all(grid[r][c] == color for r in range(r0,r1+1) for c in range(c0,c1+1)):
            sources.append(((r0+r1)//2, (c0+c1)//2, color))
    # Record rays independently; where differently colored rays cross they cancel.
    rays = {}
    for r, c, color in sources:
        for x in range(w):
            rays.setdefault((r, x), set()).add(color)
        for y in range(h):
            rays.setdefault((y, c), set()).add(color)
    for (r, c), colors in rays.items():
        if len(colors) == 1:
            out[r][c] = next(iter(colors))
        else:
            out[r][c] = 0
    return out

